{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Fimasartan, the closest analogue by Morgan similarity (0.2604), has an absolute oral bioavailability of 18.6% in healthy subjects, below the 20% threshold; its imidazole/n-butyl/N-benzyl-aryl ARB scaffold and acidic tetrazole are directly relevant to the query's two-acid imidazole ARB-like structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Olmesartan medoxomil, an imidazole ARB prodrug, gives an absolute bioavailability of about 26% for the active olmesartan, above the threshold; however, this reflects prodrug absorption and is only marginally above 20%, so it weakly contradicts a low prediction.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "Telmisartan, a non-prodrug ARB with a carboxylic acid and N-benzyl-biphenyl motif, has an absolute bioavailability of 57.4% in healthy volunteers, well above the threshold; this contradicts low but its scaffold is less similar to the query than fimasartan.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Irbesartan, an ARB with a butyl imidazolinone and tetrazole, has an absolute bioavailability of 82% in healthy volunteers, contradicting low; however, its higher F is associated with a different acid/heterocycle arrangement and lower similarity to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The closest experimental analogue, fimasartan, has absolute F = 18.6% in humans, below the 20% threshold, and the query shares the imidazole/n-butyl/N-benzyl-aryl ARB scaffold plus an additional carboxylic acid that would likely further limit permeability. Although several less-similar ARBs and carboxylic acid drugs have higher F, the directness of the fimasartan result and the query's two acidic groups tip the balance toward low; confidence is low because transfer similarities are modest and high-F analogues exist.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities to all evidence molecules are low (0.21-0.26), limiting transferability.",
    "The query's two free carboxylic acids and acrylic acid/thiophene combination are not exactly represented in any evidence molecule.",
    "Fasted-state-specific data are not explicitly reported for most analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

